    let remaining = amount;
    if (orderType === 0) {
      while (remaining > 0 && sell.length > 0 && sell[0][0] <= price) {
        const top = sell[0];
        const matched = Math.min(remaining, top[1]);
        remaining -= matched; top[1] -= matched;
        if (top[1] === 0) heapPop(sell, sellCompare);
      }
