        const matched = Math.min(remaining, top[1]);
        remaining -= matched; top[1] -= matched;
        if (top[1] === 0) heapPop(buy, buyCompare);
      }
      if (remaining > 0) heapPush(sell, [price, remaining], sellCompare);
    }
